# Вариант Б: спорт и зоопарк. Формат задачи см. build.py
V = 'B'
TASKS = [
dict(n=1, pts=0.5, title='Вход в спортзал', topics='if / elif / else, not in, and',
 text='В окне уже заданы список `members` и три фразы: `guest_msg`, `bonus_msg`, `usual_msg`. Вводятся имя посетителя и число его посещений за месяц.\n\nЕсли имени нет в списке членов клуба, напечатайте `guest_msg`. Если посетитель в списке и был не меньше 10 раз, напечатайте `bonus_msg`. Во всех остальных случаях напечатайте `usual_msg`.',
 fin='Первая строка — имя, вторая — число посещений (целое).', fout='Одна из трёх фраз.',
 pre="members = ['Аня', 'Борис', 'Вера']\nguest_msg = 'Гостевой вход'\nbonus_msg = 'Бонус за активность'\nusual_msg = 'Обычный вход'",
 inputs=[['Аня','12'],['Борис','3'],['Глеб','20'],['Вера','10'],['Аня','9'],['аня','15']],
 sol="name = input()\nvisits = int(input())\n\nif name not in members:\n    print(guest_msg)\nelif visits >= 10:\n    print(bonus_msg)\nelse:\n    print(usual_msg)\n",
 hint='Сначала отсеките тех, кого нет в списке (`not in`), потом проверьте посещения. «Не меньше 10» — это `>=`. Не забудьте `int`.',
 idea='Три исхода — цепочка `if / elif / else`: не член клуба; член с бонусом; член без бонуса.',
 steps=['`name = input()` читает имя, `visits = int(input())` читает число и сразу делает его числом.','`name not in members` — первая проверка: если человека нет, остальное не важно.','`visits >= 10` выполняется только когда он в списке; «не меньше» — это `>=`.','`else` — обычный вход.'],
 mist=['Поставили `>` вместо `>=`: посетитель с ровно 10 посещениями не получит бонус.','Забыли `int(...)`: сравнение строки с числом — ошибка `TypeError`.','Регистр важен: `аня` не равно `Аня`, такого члена клуба нет.']),
dict(n=2, pts=1, title='Быстрые бегуны', topics='while True, break, split, список',
 text='Вводятся строки вида `имя:секунд` (время забега, целое число), пока не будет введено слово `END`.\n\nНапечатайте список бегунов, которые пробежали **быстрее 60 секунд** (строго), в порядке ввода. Если таких нет, напечатайте пустой список.',
 fin='Строки `имя:секунд`, последняя строка — `END`.', fout='Список имён в квадратных скобках, как печатает `print(список)`.',
 pre='',
 inputs=[['Аня:55','Борис:60','Вера:61','END'],['END'],['Глеб:59','Даша:30','END'],['Егор:100','END'],['Зоя:60','END']],
 sol="fast = []\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    name, seconds = line.split(':')\n    if int(seconds) < 60:\n        fast.append(name)\n\nprint(fast)\n",
 hint='Список создайте до цикла. Строку режьте по двоеточию: `name, seconds = line.split(":")`. Время — строка, нужен `int`. «Быстрее» — это `<`.',
 idea='Читаем строки в бесконечном цикле, на слове `END` выходим через `break`, остальное разбираем и фильтруем.',
 steps=['`fast = []` создаём **до** цикла, иначе список обнулялся бы на каждой строке.','`while True:` — читаем, пока сами не прервём цикл.','`line == "END"` → `break`: выходим, не обрабатывая слово `END`.','`name, seconds = line.split(":")` — две части строки в две переменные.','`int(seconds) < 60` — «быстрее» строго, ровно 60 не подходит.'],
 mist=['Список создан внутри цикла — в конце останется только последний бегун.','Не сделали `int(seconds)`: сравнение строки с числом — ошибка `TypeError`.','Поставили `<=`: бегун ровно на 60 секунд попадёт зря.']),
dict(n=3, pts=0.5, title='Новое животное', topics='split(", "), in, append',
 text='В первой строке названия животных зоопарка через «запятая + пробел». Во второй — название нового животного.\n\nЕсли оно уже есть в зоопарке, напечатайте `Уже есть`. Если его нет — добавьте в конец списка и напечатайте список.',
 fin='Первая строка — животные через `, `. Вторая — одно название.', fout='Фраза `Уже есть` или список названий в квадратных скобках.',
 pre='',
 inputs=[['тигр, лев, слон','зебра'],['тигр, лев','лев'],['панда','панда'],['жираф, зебра','бегемот'],['тигр','Тигр']],
 sol="animals = input().split(', ')\nnew_animal = input()\n\nif new_animal in animals:\n    print('Уже есть')\nelse:\n    animals.append(new_animal)\n    print(animals)\n",
 hint='Строку разбейте `split(", ")`. Если животное есть (`in`) — печатаем фразу, иначе `append` и печатаем список.',
 idea='Превращаем строку в список, проверяем наличие и выбираем между двумя выводами.',
 steps=['`input().split(", ")` — строка превращается в список названий.','`new_animal in animals` — истина, если такое животное уже есть.','Если есть — только фраза; иначе `append` и печать списка.','Обе печати внутри своей ветки `if` / `else`.'],
 mist=['`split()` без аргумента: запятые останутся в кусках названий.','Напечатали список вне `else`: в первом случае вывод будет лишним.','Регистр важен: `Тигр` и `тигр` — разные названия.']),
dict(n=4, pts=1, title='Тяжёлые животные', topics='два списка, range(len())',
 text='В первой строке названия животных через пробел, во второй — их вес в килограммах (целые числа) в том же порядке. В третьей — предельный вес.\n\nНапечатайте названия животных, чей вес **строго больше** предельного, каждое с новой строки.',
 fin='Три строки: названия, веса, предельный вес.', fout='Названия по одному на строке или пустой вывод.',
 pre='',
 inputs=[['слон тигр заяц бегемот','4000 200 5 1500','1000'],['А Б','10 20','50'],['Один','300','299'],['Х У Ф','40 50 60','50'],['Лев Волк','190 40','10']],
 sol="animals = input().split()\nweights = input().split()\nlimit = int(input())\n\nfor i in range(len(animals)):\n    if int(weights[i]) > limit:\n        print(animals[i])\n",
 hint='Животные и веса лежат в двух списках, связь — одинаковый номер. Переберите номера через `range(len(...))`. Веса — строки, нужен `int`.',
 idea='Идём по номерам: по номеру берём и животное, и вес, сравниваем вес с предельным.',
 steps=['`animals` и `weights` — списки **строк**; вес берём как `int(weights[i])`.','`range(len(animals))` — номера 0, 1, 2, …','`int(weights[i]) > limit` — «строго больше», то есть `>`.','Печатаем `animals[i]` — животное с тем же номером.'],
 mist=['`>=` вместо `>`: животное с весом ровно как предельный попадёт зря.','Сравнили `weights[i] > limit` без `int`: строка с числом — ошибка `TypeError`.','Напечатали `weights[i]` вместо `animals[i]`.']),
dict(n=5, pts=0.75, title='Все виды спорта', topics='множества, объединение',
 text='Две строки: виды спорта первой секции и второй (через пробел).\n\nНапечатайте, сколько **различных** видов спорта в двух секциях вместе.',
 fin='Две строки, названия через пробел.', fout='Одно число.',
 pre='',
 inputs=[['футбол теннис бокс','бокс плавание'],['йога','йога'],['а б в','г д'],['хоккей','хоккей лыжи биатлон'],['шахматы го','го шахматы']],
 sol="first = set(input().split())\nsecond = set(input().split())\n\nprint(len(first | second))\n",
 hint='Превратите обе строки во множества. «Вместе, без повторов» — это объединение `|`.',
 idea='Объединение двух множеств хранит каждый вид спорта один раз, даже если он есть в обеих секциях.',
 steps=['`set(input().split())` — строка → список → множество.','`first | second` — виды спорта хотя бы одной секции, без повторов.','`len(...)` — сколько их.'],
 mist=['Сложили `len(first) + len(second)`: общий вид спорта посчитается дважды.','`&` вместо `|`: получатся только виды, общие для обеих секций.','`first + second`: сложение множеств не работает, будет `TypeError`.']),
dict(n=6, pts=1.25, title='Новые секции', topics='множества, объединение и разность',
 text='Три строки с названиями видов спорта через запятую **без пробела** (в названиях пробелы бывают): секция А; секция Б; виды спорта, которые уже есть в школе.\n\nНапечатайте, сколько видов спорта есть в секции А **или** Б, но **нет в школе**.',
 fin='Три строки, виды через запятую.', fout='Одно число.',
 pre='',
 inputs=[['футбол,теннис','теннис,бокс','футбол'],['конный спорт,йога','йога','йога'],['Х','Х','Х'],['плавание','лыжи,биатлон','шахматы'],['дзюдо,самбо','самбо,каратэ','дзюдо,каратэ,сумо']],
 sol="first = set(input().split(','))\nsecond = set(input().split(','))\nschool = set(input().split(','))\n\nsections = first | second\nprint(len(sections - school))\n",
 hint='Сначала объедините секции `|`, потом вычтите `-` виды, которые уже есть в школе.',
 idea='Собираем все виды спорта двух секций (объединение) и вычитаем те, что уже есть в школе.',
 steps=['Разделитель — запятая без пробела: `.split(",")`. Без аргумента названия с пробелами разорвутся.','`first | second` — виды спорта хотя бы одной секции.','`sections - school` — те из них, которых нет в школе.','`len(...)` — сколько их.'],
 mist=['`split()` вместо `split(",")`: «конный спорт» разорвётся на два вида.','Вычли в другую сторону `school - sections`: получится совсем другое множество.','`&` вместо `|` в первом шаге: получатся виды, которые есть в обеих секциях.']),
dict(n=7, pts=0.75, title='Животные вольера', topics='словарь, перебор ключей',
 text='В окне задан словарь `cages`: животное → номер вольера (число). Вводится номер вольера.\n\nНапечатайте животных из этого вольера, каждое с новой строки, в порядке словаря. Если таких нет, ничего не печатайте.',
 fin='Одна строка — номер вольера (целое число).', fout='Названия по одному на строке или пустой вывод.',
 pre="cages = {'тигр': 1, 'лев': 1, 'зебра': 2, 'жираф': 2, 'слон': 3, 'бегемот': 3, 'панда': 4}",
 inputs=[['1'],['2'],['3'],['4'],['9']],
 sol="number = int(input())\n\nfor animal in cages:\n    if cages[animal] == number:\n        print(animal)\n",
 hint='Цикл `for animal in cages` перебирает **ключи** (животных). Номер вольера берётся как `cages[animal]`. Введённый номер — строка, нужен `int`.',
 idea='Идём по животным и печатаем тех, у кого номер вольера совпадает с введённым.',
 steps=['`number = int(input())` — номера в словаре числа, значит и введённое нужно сделать числом.','`for animal in cages:` — переменная `animal` по очереди получает каждое животное.','`cages[animal] == number` — совпадение номера.','Печатаем `animal`, а не номер.'],
 mist=['Забыли `int(...)`: `1 == "1"` даёт `False`, и ничего не напечатается.','Напечатали `cages[animal]`: получится номер вольера вместо животного.','Ждали, что цикл даст значения: он перебирает ключи.']),
dict(n=8, pts=1.25, title='Спортсмены с рекордом', topics='словарь списков, min',
 text='В окне задан словарь `athletes`: спортсмен → список времён забегов в секундах. Вводится норматив.\n\nНапечатайте спортсменов, у которых **хотя бы один** забег был **быстрее** норматива (строго меньше), каждого с новой строки, в порядке словаря.',
 fin='Одна строка — норматив (целое число).', fout='Имена по одному на строке или пустой вывод.',
 pre="athletes = {'Аня': [62, 58, 60], 'Борис': [70, 72, 69], 'Вера': [55, 57, 56], 'Глеб': [61, 63, 64]}",
 inputs=[['60'],['56'],['70'],['50'],['100']],
 sol="limit = int(input())\n\nfor athlete in athletes:\n    if min(athletes[athlete]) < limit:\n        print(athlete)\n",
 hint='«Хотя бы один забег быстрее» — это то же, что «лучшее время меньше норматива». Используйте `min`.',
 idea='Вместо проверки каждого забега сравниваем с нормативом минимум в списке.',
 steps=['`athletes[athlete]` — список времён спортсмена.','`min(...)` — лучшее (самое маленькое) время.','Если лучшее время меньше норматива, то хотя бы один забег подходит. Строго «меньше» — это `<`.','Печатаем **ключ** `athlete`, а не список.'],
 mist=['`max` вместо `min`: условие станет «все забеги быстрее норматива».','`<=` вместо `<`: спортсмен с лучшим временем ровно в норматив попадёт зря.','Напечатали `athletes[athlete]` — список вместо имени.']),
dict(n=9, pts=1.5, title='Автобусы для групп', topics='цикл, //, %, if',
 text='Первая строка — число человек в каждой группе экскурсантов, через пробел. Вторая — вместимость одного автобуса (целое число). Каждая группа едет отдельно, свободные места другим группам не отдаются.\n\nНапечатайте, сколько автобусов понадобится на все группы.',
 fin='Две строки: размеры групп, вместимость автобуса.', fout='Одно число.',
 pre='',
 inputs=[['25 40 10','20'],['7','10'],['100 100','25'],['1 2 3','2'],['50','7']],
 sol="groups = input().split()\ncapacity = int(input())\n\nbuses = 0\nfor group in groups:\n    buses += int(group) // capacity\n    if int(group) % capacity != 0:\n        buses += 1\n\nprint(buses)\n",
 hint='Для одной группы полные автобусы — `//`. Если остаток `%` не ноль, нужен ещё один автобус. Счётчик создайте до цикла.',
 idea='Для каждой группы считаем полные автобусы делением нацело и добавляем ещё один, если кто-то остался.',
 steps=['`groups` — список **строк**, каждую берём как `int(group)`.','`int(group) // capacity` — полные автобусы.','`int(group) % capacity != 0` — остались люди, нужен ещё автобус.','`buses = 0` до цикла, печатаем после.'],
 mist=['Только `//` без проверки остатка: неполный автобус потеряется.','Обнулили счётчик внутри цикла: останутся данные последней группы.','Забыли `int(group)`: деление `//` со строкой — ошибка.'],
 trace='Группы `25 40 10`, автобус на 20: 25 → 1 полный и остаток 5, значит 2; 40 → 2 полных, остатка нет, значит 2; 10 → 0 полных, остаток 10, значит 1. Итого 5.'),
dict(n=10, pts=1.5, title='Самый слабый игрок', topics='while True, словарь-накопитель, минимум',
 text='Вводятся строки вида `игрок,очки` (очки — целое **положительное** число), пока не будет введено слово `END`. Один игрок может встретиться несколько раз.\n\nНайдите игрока с **наименьшей суммой** очков. Напечатайте его имя и сумму через пробел. Гарантируется, что есть хотя бы одна строка. Если таких несколько, выберите того, кто встретился в списке раньше.',
 fin='Строки `игрок,очки`, последняя строка — `END`.', fout='Имя и число через пробел.',
 pre='',
 inputs=[['Аня,10','Борис,4','Аня,15','Борис,6','Вера,25','END'],['Глеб,5','END'],['А,10','Б,10','END'],['Х,100','У,50','У,60','END'],['Д,3','Е,2','Д,1','Е,7','END']],
 sol="totals = {}\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    player, points = line.split(',')\n    if player in totals:\n        totals[player] += int(points)\n    else:\n        totals[player] = int(points)\n\nworst = ''\nfor player in totals:\n    if worst == '' or totals[player] < totals[worst]:\n        worst = player\n\nprint(worst, totals[worst])\n",
 hint='Два шага: (1) в цикле копите суммы в словаре; (2) после цикла найдите минимум. Первого игрока берите как стартового, для равных сумм сравнивайте строго `<`.',
 idea='Сначала собираем словарь «игрок → сумма», потом ищем ключ с наименьшим значением.',
 steps=['`totals = {}` — до цикла.','Если игрок уже есть, прибавляем `totals[player] += int(points)`, иначе создаём запись.','`worst = ""` — пока никого не выбрали; `worst == ""` берёт первого игрока без сравнения.','`<` (строго) оставляет первого из равных.','Печатаем после цикла имя и его сумму.'],
 mist=['Стартовое значение `0` вместо проверки пустого имени: ни одна сумма не окажется меньше нуля.','`min(totals)` без `key` берёт минимум **по алфавиту имён**, а не по сумме.','`<=` вместо `<`: при равных суммах выберется последний, а не первый.'],
 trace='Аня: 10 + 15 = 25, Борис: 4 + 6 = 10, Вера: 25. Минимум 10 у Бориса. Ответ `Борис 10`.'),
]
